True def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    boundary = {grid[r][c] for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                if r in (r0, r1) or c in (c0, c1)}
    inside = {}
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            v = grid[r][c]
            if v and v not in boundary:
                inside[v] = inside.get(v, 0) + 1
    color = max(inside, key=inside.get)
    inner = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1) if grid[r][c] == color]
    ir0 = min(r for r, c in inner); ir1 = max(r for r, c in inner)
    ic0 = min(c for r, c in inner); ic1 = max(c for r, c in inner)
    top, bottom = ir0-r0, r1-ir1
    left, right = ic0-c0, c1-ic1
    out = [row[:] for row in grid]
    for r in range(max(0, r0-top), min(h, r1+bottom+1)):
        for c in range(max(0, c0-left), min(w, c1+right+1)):
            if out[r][c] == 0:
                out[r][c] = color
    return out
